import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.D4KxWb5R.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"src/en/guide/getting-started.md"}'),n={name:"en/guide/getting-started.md"};function r(s,e,d,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>M&#39;City IQ is invitation-only: there is no open sign-up.</p><h2 id="receiving-your-invitation" tabindex="-1">Receiving your invitation <a class="header-anchor" href="#receiving-your-invitation" aria-label="Permalink to &quot;Receiving your invitation&quot;">​</a></h2><p>The general administrator creates your account with your position and scope. You then receive an invitation e-mail, at the address entered, with a <strong>temporary password</strong>.</p><ul><li>The invitation is valid for <strong>7 days</strong> by default (set by M&#39;City in the <a href="./administration/settings.html">configuration</a>).</li><li>An expired invitation is never renewed automatically: ask the general administrator to send you a new one.</li><li>A new invitation replaces the previous one: the old temporary password stops working.</li></ul><h2 id="first-sign-in" tabindex="-1">First sign-in <a class="header-anchor" href="#first-sign-in" aria-label="Permalink to &quot;First sign-in&quot;">​</a></h2><ol><li>Open the M&#39;City IQ sign-in page and enter your e-mail address and the temporary password.</li><li>If two-factor authentication is required, enter the code received by e-mail (see below).</li><li>The <strong>Choose your password</strong> screen appears: choose your own. It must be at least <strong>12 characters</strong> long by default.</li><li>You land on <a href="./desk.html">your desk</a>.</li></ol><p>Until this password is chosen, the rest of the platform stays out of reach.</p><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Enter your e-mail and password, then <strong>Log in</strong>. Tick <strong>Remember me</strong> to stay signed in on this browser.</p><p>If you have registered a passkey, use <strong>Sign in with a passkey</strong>: no password or code is asked.</p><p>After <strong>30 minutes</strong> without activity (a duration M&#39;City can change), you are signed out of the intranet and the back-office.</p><h2 id="two-factor-authentication" tabindex="-1">Two-factor authentication <a class="header-anchor" href="#two-factor-authentication" aria-label="Permalink to &quot;Two-factor authentication&quot;">​</a></h2><p>Two-factor authentication can be required for your account or for every account. It is then asked at each sign-in, in one of these ways:</p><table tabindex="0"><thead><tr><th>Your account has…</th><th>What you are asked</th></tr></thead><tbody><tr><td>A passkey</td><td>Nothing more: the passkey counts as both factors.</td></tr><tr><td>An authenticator app</td><td>The app&#39;s 6-digit code, or a recovery code.</td></tr><tr><td>Neither</td><td>A <strong>sign-in code sent by e-mail</strong>.</td></tr></tbody></table><h3 id="the-e-mail-code" tabindex="-1">The e-mail code <a class="header-anchor" href="#the-e-mail-code" aria-label="Permalink to &quot;The e-mail code&quot;">​</a></h3><p>The <strong>Check your email</strong> screen shows the address the code was sent to.</p><ul><li>The code has <strong>6 digits</strong> and is valid for <strong>15 minutes</strong>.</li><li>You get <strong>5 attempts</strong>; a code works only once.</li><li><strong>Send a new code</strong> sends another, at most once a minute.</li><li>Tick <strong>Remember this device for 30 days</strong>: this browser won&#39;t ask for a code for 30 days. These devices are listed in <a href="./account.html#remembered-devices">My account → Security</a>.</li></ul><p>No code? Check your spam folder, then send a new one.</p><p>The authenticator app and passkeys stay optional; add them in <a href="./account.html#security">My account → Security</a>.</p><h2 id="forgotten-password" tabindex="-1">Forgotten password <a class="header-anchor" href="#forgotten-password" aria-label="Permalink to &quot;Forgotten password&quot;">​</a></h2><ol><li>On the sign-in page, click <strong>Forgot your password?</strong>.</li><li>Enter your e-mail, then <strong>Email password reset link</strong>.</li><li>Open the link received (valid for 60 minutes) and choose a new password.</li></ol><p>Changing or resetting your password forgets all your remembered devices.</p><h2 id="disabled-account" tabindex="-1">Disabled account <a class="header-anchor" href="#disabled-account" aria-label="Permalink to &quot;Disabled account&quot;">​</a></h2><p>A disabled account (someone who left M&#39;City) can no longer sign in, neither to M&#39;City IQ nor to the product back-offices. It is never deleted: only the CEO can reactivate it.</p>',25)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
